param([int]$Batch=1,[switch]$Baseline,[string]$Case='')
$ErrorActionPreference='Stop';$repo=[IO.Path]::GetFullPath("$PSScriptRoot/../..")
$out="$repo/build-extractors/runtime-test/second-ten-ten-20261112/$(Get-Date -Format yyyyMMdd-HHmmss-fff)";[void][IO.Directory]::CreateDirectory($out)
& "$PSScriptRoot/Invoke-WithRuntimeDiagnostics.ps1" -EvidenceDirectory "$out/evidence" -RuntimeDirectories @($out) -Test {
 $mode=if($Baseline){'baseline'}else{'fixed'}
 $prepare=if($Batch -eq 1){'prepare_second_ten_ten_20261112.py'}elseif($Batch -eq 2){'prepare_second_ten_ten_20261112_second.py'}elseif($Batch -eq 3){'prepare_second_ten_ten_20261112_third.py'}elseif($Batch -eq 4){'prepare_second_ten_ten_20261112_fourth.py'}elseif($Batch -eq 5){'prepare_second_ten_ten_20261112_fifth.py'}else{throw 'Unimplemented batch'}
 & C:/Users/Admin/.cache/codex-runtimes/codex-primary-runtime/dependencies/python/python.exe "$PSScriptRoot/$prepare" $out $mode
 if($LASTEXITCODE){throw 'Extraction failed'}
 $keys=@(Get-Content "$out/cases.json" -Raw|ConvertFrom-Json);$indices=if($Case){$index=[Array]::IndexOf($keys,$Case);if($index -lt 0){throw 'Unknown case'};@($index)}else{@(0..9)}
 $failures=@('Ordinary forfeit applies health penalty','Actual wild GUID is released exactly once','Repeated finish cannot replay XP or callbacks','A temporary swap lock cannot cancel earned experience','All crossed native thresholds trigger their level side effects','MoveType zero must reach its leave switch arm','Equal-weight ordering must be irreflexive','A fresh proposal requires fresh answers from both sides','Replacing a pending request must release its earlier allocation','Admission must measure the actual two participants')
 if($Batch -eq 2){$failures=@('An unrelated player cannot cancel another duel request','A dead challenged player is rejected','A webbed forfeiter cannot flee an unwebbed opponent','A dead active pet cannot admit ordinary abilities','Native type-restricted other allies receive12 once and caster is untouched','Marked target supplies the native bonus and damage is calculated once','Aquatic pet reduces native periodic fungus damage by half','Use-based ramping still advances on a miss','Native removal expires the named aura only on its actual target','Native weather bonus is included before division across three enemies')}
 if($Batch -eq 3){$failures=@('Clicking the same owned companion dismisses it without resummoning','Repeated APPLY retains the requested favorite flag','A locked combat slot cannot accept a journal pet','An empty recipient roster cannot pacify either duel participant','A native ability lock retains its separate lock duration and ordinary cooldown','A saved zero-health journal pet must remain dead on admission','Unchanged saved experience must not be reported as a new award','Large queue sample counts retain the native weighted mean without32bit overflow','Journal removal dismisses the matching companion and clears combat references','A name query cannot bind another journal pet to the current creature')}
 $testSource=if($Batch -eq 1){'SecondTenTen20261112FirstTest.cpp'}elseif($Batch -eq 2){'SecondTenTen20261112SecondTest.cpp'}elseif($Batch -eq 3){'SecondTenTen20261112ThirdTest.cpp'}elseif($Batch -eq 4){'SecondTenTen20261112FourthTest.cpp'}else{'SecondTenTen20261112FifthTest.cpp'}
 $vs=& "${env:ProgramFiles(x86)}/Microsoft Visual Studio/Installer/vswhere.exe" -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath
 [IO.File]::WriteAllText("$out/build.cmd","@echo off`ncall `"$vs/VC/Auxiliary/Build/vcvars64.bat`" >nul`ncl /nologo /EHsc /std:c++17 /W4 /MD /fsanitize=address /Zi /I`"$out`" `"$PSScriptRoot/$testSource`" /Fe`"$out/test.exe`" /Fo`"$out/test.obj`" /Fd`"$out/compiler.pdb`"`nexit /b %errorlevel%`n")
 & cmd.exe /d /c "`"$out/build.cmd`" > `"$out/build.log`" 2>&1";if($LASTEXITCODE){Get-Content "$out/build.log" -Tail 18;throw 'Fixture compilation failed'}
 foreach($index in $indices){
  [IO.File]::WriteAllText("$out/run.cmd","@echo off`ncall `"$vs/VC/Auxiliary/Build/vcvars64.bat`" >nul`n`"$out/test.exe`" $index`nexit /b %errorlevel%`n")
  & cmd.exe /d /c "`"$out/run.cmd`" > `"$out/run-$index.log`" 2>&1";$code=$LASTEXITCODE;$raw=Get-Content "$out/run-$index.log" -Raw
  if($Baseline -and ($Batch -eq 4 -or ($Batch -eq 5 -and $index -lt 9))){if(!$code -or !$raw.Contains('AddressSanitizer: heap-use-after-free')){Get-Content "$out/run-$index.log" -Tail 10;throw "Expected source lifetime counterfactual missing:$($keys[$index])"};"PASS expected-broken pinned heap-use-after-free:$($keys[$index]);paired repaired run required"}
  elseif($Baseline -and $Batch -eq 5){if($code -ne 1 -or !$raw.Contains('Missing first ally type cannot block another eligible injured ally')){throw 'Expected healer target-selection counterfactual missing'};'PASS expected-broken pinned healer target selection; paired fixed required'}
  elseif($Baseline){if($code -ne 1 -or $raw.Trim() -cne $failures[$index]){throw "Expected pinned assertion missing:$($keys[$index])"};"PASS expected-broken pinned counterfactual:$($keys[$index]);paired repaired run required"}
  elseif($code -or !$raw.Contains('PASS complete production')){Get-Content "$out/run-$index.log" -Tail 18;throw "Regression failed:$($keys[$index])"}else{"$($keys[$index]):$($raw.Trim())"}
 }
}
$global:LASTEXITCODE=0
